select t.spec_type,t.spec_type specType,t.spec_id,t.spec_id specId,t.spec_name,t.spec_name
specName,t.spec_holdplace,t.spec_holdplace specHoldplace,t.spec_value_type,t.spec_value_type
specValueType,t.domain,t.spec_cd,t.spec_cd specCd,t.status_cd,t.status_cd statusCd,t.spec_show,t.spec_show
specShow,t.required,t.table_name,t.table_name tableName,t.list_show,t.list_show listShow
from attr_spec t
where 1 =1

    and t.spec_type= #{specType}


    and t.spec_id= #{specId}


    and t.spec_name= #{specName}


    and t.spec_holdplace= #{specHoldplace}


    and t.spec_value_type= #{specValueType}


    and t.domain= #{domain}


    and t.spec_cd= #{specCd}


    and t.status_cd= #{statusCd}


    and t.spec_show= #{specShow}


    and t.required= #{required}


    and t.table_name= #{tableName}


    and t.list_show= #{listShow}

order by t.create_time desc

    limit #{page}, #{row}

